import React from 'react';
import styles from "./MyProfile.module.css";

function MyProfile() {
    return (
        <div className={styles.MyProfileOutContainer}>
            <div className={styles.MyProfileContainer}>
                
                <header className={styles.Header}>
                    {/* Кнопка "Назад" слева или справа, как удобнее. Сделал справа как было */}
                    <div style={{width: '40px'}}></div> {/* Пустышка для центровки заголовка */}
                    <div className={styles.PageName}>Профиль</div>
                    <div className={styles.StrelkaPlace}>
                        <img className={styles.Strelka} src="images/back.svg" alt="Go back" />
                    </div>
                </header>

                <div className={styles.ContentWrapper}>
                    {/* Фото */}
                    <div className={styles.PhotoPlace}>
                        <img className={styles.MyPhoto} src="images/artem.jpg" alt="User Avatar" />
                    </div>

                    {/* Никнейм */}
                    <div className={styles.MyNick}>Genius</div>

                    {/* Данные - используем Flex для выравнивания строк */}
                    <div className={styles.InfoBlock}>
                        <div className={styles.Row}>
                            <span className={styles.Label}>Дата рождения:</span>
                            <span className={styles.Value}>01.01.2000</span>
                        </div>
                        <div className={styles.Row}>
                            <span className={styles.Label}>О себе:</span>
                            <span className={styles.Value}>Software Engineer Student</span>
                        </div>
                    </div>

                    {/* Кнопка */}
                    <div className={styles.ButtonPlace}>
                        <button className={styles.Button}>Изменить Профиль</button>
                    </div>
                </div>

            </div>
        </div>
    );
}

export default MyProfile;
